-- recursive CTEs: UNION vs UNION ALL, cycles, SEARCH and CYCLE, depth limits, errors
create table edge (src int, dst int);
insert into edge values (1, 2), (2, 3), (3, 4), (2, 5), (5, 3), (4, 1), (6, 6), (7, null);
create table tree (id int primary key, parent int, name text);
insert into tree values (1, null, 'root'), (2, 1, 'a'), (3, 1, 'b'), (4, 2, 'a1'), (5, 2, 'a2'), (6, 3, 'b1'), (7, 6, 'b1x'), (8, null, 'other'), (9, 8, 'o1');
with recursive t(n) as (select 1 union all select n + 1 from t where n < 5) select * from t;
with recursive t(n) as (select 1 union select n + 1 from t where n < 5) select sum(n) from t;
with recursive t(n) as (values (1) union all select n * 2 from t where n < 1000) select max(n), count(*) from t;
with recursive t(n) as (select 1 union all select n + 1 from t) select n from t limit 7;
with recursive t(n) as (select 0 union select (n + 1) % 4 from t) select n from t order by n;
with recursive t(n) as (select 0 union all select (n + 1) % 4 from t) select n from t limit 10;
with recursive reach(node) as (select 1 union select e.dst from edge e join reach r on e.src = r.node) select node from reach order by node;
with recursive reach(node) as (select 6 union select e.dst from edge e join reach r on e.src = r.node) select * from reach;
with recursive reach(node) as (select 7 union select e.dst from edge e join reach r on e.src = r.node) select * from reach;
with recursive reach(node, depth) as (select 1, 0 union all select e.dst, r.depth + 1 from edge e join reach r on e.src = r.node where r.depth < 5) select node, min(depth) from reach group by node order by node;
with recursive p(node, path) as (select 1, array[1] union all select e.dst, p.path || e.dst from edge e join p on e.src = p.node where not e.dst = any (p.path)) select path from p order by path;
with recursive p(node, path, cyc) as (select 1, array[1], false union all select e.dst, p.path || e.dst, e.dst = any (p.path) from edge e join p on e.src = p.node where not p.cyc) select path, cyc from p where cyc order by path;
with recursive sub(id, name, lvl) as (select id, name, 0 from tree where parent is null union all select t.id, t.name, s.lvl + 1 from tree t join sub s on t.parent = s.id) select * from sub order by id;
with recursive sub(id, path) as (select id, name from tree where id = 1 union all select t.id, s.path || '/' || t.name from tree t join sub s on t.parent = s.id) select * from sub order by path;
with recursive anc(id, parent) as (select id, parent from tree where id = 7 union all select t.id, t.parent from tree t join anc a on t.id = a.parent) select id from anc order by id;
with recursive cnt(id, n) as (select id, 1 from tree union all select t.parent, c.n from cnt c join tree t on t.id = c.id where t.parent is not null) select id, sum(n) from cnt group by id order by id;
with recursive t(n, s) as (select 1, 'x'::text union all select n + 1, s || 'x' from t where n < 4) select * from t;
with recursive t(n, s) as (select 1, 'x' union all select n + 1, s || 'x' from t where n < 4) select * from t;
with recursive t(n) as (select 1::numeric union all select n / 2 from t where n > 0.1) select n from t;
with recursive t(n) as (select 1 union all select n + 0.5 from t where n < 3) select n from t;
with recursive t(a, b) as (select 0, 1 union all select b, a + b from t where b < 100) select a from t;
with recursive fact(n, f) as (select 1, 1::numeric union all select n + 1, f * (n + 1) from fact where n < 25) select f from fact where n = 25;
with recursive t(n) as (select 1 union all select n + 1 from t where n < 3), u(m) as (select n * 10 from t) select * from u;
with recursive t(n) as (select 1 union all select n + 1 from t where n < 3) select * from t a, t b where a.n < b.n;
with recursive t(n) as (select 1 union all select n + 1 from t where n < 3) select (select count(*) from t), (select max(n) from t);
with recursive a(n) as (select 1 union all select n + 1 from a where n < 3), b(m) as (select n from a union all select m + 10 from b where m < 20) select * from b order by m;
with recursive t(n) as (select 1 union all select n + 1 from t where n < 3) select * from t union all select * from t order by 1;
with recursive t(x) as (select 1 union all select x + 1 from t where x < 2) select * from t where x in (with recursive u(y) as (select 2 union all select y + 1 from u where y < 4) select y from u);
with recursive t(n) as (select 1 union all select n + 1 from t where n < 5) search depth first by n set ord select * from t order by ord;
with recursive sub(id, parent) as (select id, parent from tree where parent is null union all select t.id, t.parent from tree t join sub s on t.parent = s.id) search depth first by id set ord select id from sub order by ord;
with recursive sub(id, parent) as (select id, parent from tree where parent is null union all select t.id, t.parent from tree t join sub s on t.parent = s.id) search breadth first by id set ord select id from sub order by ord, id;
with recursive sub(id, parent) as (select id, parent from tree where parent is null union all select t.id, t.parent from tree t join sub s on t.parent = s.id) search depth first by id set ord select id, ord from sub order by ord;
with recursive r(node) as (select 1 union all select e.dst from edge e join r on e.src = r.node) cycle node set is_cycle using path select node, is_cycle, path from r order by path;
with recursive r(node) as (select 1 union all select e.dst from edge e join r on e.src = r.node) cycle node set is_cycle to 'Y' default 'N' using path select node, is_cycle from r where is_cycle = 'Y' order by node;
with recursive r(node) as (select 6 union all select e.dst from edge e join r on e.src = r.node) cycle node set c using p select * from r;
with recursive r(node, d) as (select 1, 0 union all select e.dst, d + 1 from edge e join r on e.src = r.node) cycle node set c using p select max(d) from r;
with recursive t(n) as (select 1 union all select n + 1 from t where n < 3) search depth first by n set n select * from t;
with recursive t(n) as (select 1 union all select n + 1 from t where n < 3) cycle n set c using n select * from t;
with recursive t(n) as (select 1 union all select n + 1 from t where n < 3) search depth first by m set o select * from t;
with recursive t(n) as (select n from t) select * from t;
with recursive t(n) as (select 1 union all select n + 1 from t where n < 3 union all select 5) select * from t;
with recursive t(n) as (select 1 intersect select n + 1 from t) select * from t;
with recursive t(n) as (select 1 union all select count(*) from t) select * from t;
with recursive t(n) as (select 1 union all select n + 1 from t t1, t t2 where t1.n < 3) select * from t;
with recursive t(n) as (select 1 union all select n + 1 from t where n < 3 order by 1) select * from t;
with recursive t(n) as (select 1 union all select n + 1 from t where n < 3 limit 1) select * from t;
with recursive t(n) as (select 1 union all select (select n + 1 from t) where false) select * from t;
with recursive t(n) as (select 1 union all select n + x from t left join (select 2 as x) y on true where n < 5) select * from t;
with recursive t(n) as (select 1 union all select x from (select 2 as x) y left join t on true where x < 1) select * from t;
with recursive t(n) as (select 1 union all select n + 1 from t where n < 3 and exists (select 1 from t)) select * from t;
with recursive t(n) as (select 1 union all select 'a' from t) select * from t;
with recursive t(n) as (select 1 union all select n::bigint + 1 from t where n < 3) select * from t;
with recursive t(n) as (select 1::bigint union all select n + 1 from t where n < 3) select pg_typeof(n) from t limit 1;
with recursive t(n) as (select 'a'::varchar(3) union all select n || 'b' from t where length(n) < 3) select * from t;
with recursive t(n) as (select 1 union all select n + 1 from t where n < 200) select count(*), sum(n) from t;
with recursive t(n) as (select 1 union select n from t) select * from t;
with recursive t(n, m) as (select 1, null::int union all select n + 1, n from t where n < 3) select * from t;
with recursive t(n) as (select null::int union select 1 from t) select * from t;
with recursive t(a) as (select array[1] union all select a || (a[array_length(a, 1)] + 1) from t where array_length(a, 1) < 4) select a from t;
with recursive t(j) as (select '{"a":{"b":{"c":1}}}'::jsonb union all select v from t, jsonb_each(t.j) e(k, v) where jsonb_typeof(v) = 'object') select j from t;
with recursive w(s, rest) as (select '', 'hello' union all select s || substr(rest, 1, 1), substr(rest, 2) from w where rest <> '') select s from w order by length(s);
with recursive dates(d) as (select date '2024-01-29' union all select d + 1 from dates where d < date '2024-03-02') select count(*), min(d), max(d) from dates;
with recursive t(n) as (select 1 union all select n + 1 from t where n < 4) insert into edge select n, n * 100 from t;
select count(*) from edge;
with recursive t(n) as (select 1 union all select n + 1 from t where n < 4) delete from edge where dst in (select n * 100 from t);
select count(*) from edge;
with recursive t(n) as (select 2 union all select n + 1 from t where n < 3) update tree set name = upper(name) where id in (select n from t) returning id, name;
-- theatre data
with recursive src(prod_id, origin, depth) as (select prod_id, based_on, 1 from production where based_on is not null union all select s.prod_id, p.based_on, s.depth + 1 from src s join production p on p.prod_id = s.origin where p.based_on is not null and s.depth < 10) select prod_id, max(depth) from src group by prod_id having max(depth) > 1 order by 1;
with recursive anc(pid) as (select based_on from production where prod_id = (select max(prod_id) from production where based_on is not null) union select p.based_on from production p join anc on p.prod_id = anc.pid where p.based_on is not null) select count(*) from anc;
with recursive anc(pid) as (select based_on from production where prod_id = (select max(prod_id) from production where based_on is not null) union all select p.based_on from production p join anc on p.prod_id = anc.pid where p.based_on is not null) select count(*) >= 1 from anc;
with recursive anc(c, p) as (select prod_id, based_on from production where based_on is not null union select anc.c, q.based_on from anc join production q on q.prod_id = anc.p where q.based_on is not null) select count(*) from anc;
with recursive anc(c, p) as (select prod_id, based_on from production where based_on is not null union select anc.c, q.based_on from anc join production q on q.prod_id = anc.p where q.based_on is not null) select c from anc where c = p order by 1;
with recursive anc(c, p) as (select prod_id, based_on from production where based_on is not null union select anc.c, q.based_on from anc join production q on q.prod_id = anc.p where q.based_on is not null) select p, count(*) from anc group by p order by 2 desc, 1 limit 5;
with recursive anc(c, p) as (select prod_id, based_on from production where based_on is not null union all select anc.c, q.based_on from anc join production q on q.prod_id = anc.p where q.based_on is not null) cycle c, p set is_cycle using path select count(*), count(*) filter (where is_cycle) from anc;
with recursive days(d) as (select min(perf_date) from performance union all select d + 7 from days where d + 7 <= (select max(perf_date) from performance)) select count(*), sum((select count(*) from performance where perf_date >= d and perf_date < d + 7)) from days;
with recursive chain(id, depth) as (select mentor_id, 1 from mentor where mentee_id = (select min(mentee_id) from mentor) union all select m.mentor_id, c.depth + 1 from chain c join mentor m on m.mentee_id = c.id where c.depth < 6) select * from chain;
with recursive down(id, depth, path) as (select person_id, 0, array[person_id::text] from artist a where not exists (select 1 from mentor m where m.mentee_id = a.person_id) and exists (select 1 from mentor m where m.mentor_id = a.person_id) union all select m.mentee_id, d.depth + 1, d.path || m.mentee_id::text from down d join mentor m on m.mentor_id = d.id where not m.mentee_id = any (d.path)) select max(depth), count(*), count(distinct id) from down;
with recursive down(id) as (select mentor_id from mentor union select m.mentee_id from down d join mentor m on m.mentor_id = d.id) search depth first by id set ord select count(*) from down;
with recursive down(id, depth) as (select (select min(mentor_id) from mentor), 0 union all select m.mentee_id, d.depth + 1 from down d join mentor m on m.mentor_id = d.id where d.depth < 10) search breadth first by id set ord select id, depth from down order by ord;
with recursive r(node) as (select 1 union all select e.dst from edge e join r on e.src = r.node) search depth first by node set ord cycle node set is_cycle using path select node, ord, is_cycle from r order by ord;
with recursive r(node) as (select 1 union all select e.dst from edge e join r on e.src = r.node) search breadth first by node set ord cycle node set is_cycle using path select node, is_cycle from r order by ord, node;
with recursive r(a, b) as (select 1, 2 union all select b, e.dst from r join edge e on e.src = r.b) cycle a, b set c using p select a, b, c, p from r order by p;
with recursive r(node) as (select 1 union select e.dst from edge e join r on e.src = r.node) cycle node set c using p select count(*) from r;
with recursive r(node) as (select 1 union all select e.dst from edge e join r on e.src = r.node) cycle node set c to 1 default 0 using p select sum(c), pg_typeof(max(c)) from r;
with recursive r(node) as (select 1 union all select e.dst from edge e join r on e.src = r.node) cycle node set c to 1 default 'x' using p select * from r;
with recursive r(node) as (select 1 union all select e.dst from edge e join r on e.src = r.node) cycle zz set c using p select * from r;
with recursive r(node) as (select 1 union all select e.dst from edge e join r on e.src = r.node) cycle node set c using c select * from r;
with recursive t(n, k) as (select 1, 'a' union all select n + 1, k from t where n < 4) search breadth first by k, n set o select n, o from t order by o;
with recursive t(n) as (select 3 union all select n - 1 from t where n > 0) search depth first by n set o select n, o from t order by o desc;
with recursive t(n) as (select 1 union all select n + 1 from (select * from t) x where n < 3) select * from t;
with recursive t(n) as (select 1 union all (select n + 1 from t where n < 3 limit 1)) select * from t;
with recursive t(n) as (select 1 union all select n + 1 from t where n < 3 offset 0) select * from t;
with recursive t(n) as (select 1 union all select n + 1 from t full join (select 2 as x) y on true where n < 3) select * from t;
with recursive t(n) as (select 1 union all select n + 1 from t left join (select 2 as x) y on true where n < 3) select * from t;
with recursive t(n) as (select 1 union all select n + 1 from t where n < 3 group by n) select * from t;
with recursive t(n) as (select 1 union all select distinct n + 1 from t where n < 3) select * from t;
with recursive t(n) as (select 1 union all select n + 1 from t where n < 1000) select count(*) from t;
with recursive t(n) as (select 1 union all select n + 1 from t where n < 3) select * from t where n = (select max(n) from t);
